   ]
  },
  {
   "name": "Core: errors",
   "responsibility": "Framework-agnostic domain exceptions (AppError hierarchy) plus register_exception_handlers(app), which maps AppError, HTTPException, RequestValidationError, SQLAlchemyError and Exception to JSON {detail}.",
