   "responses": {
    "201": "LinkCreatedResponse {code, short_url, url, is_active, created_at}. Header Location: /api/links/{code}. On replay (same key and same url) the body is identical to the original and the header Idempotent-Replayed: true is added. The first response omits that header.",
    "400": "{\"detail\": \"Invalid Idempotency-Key header\"}: the header is empty/blank or longer than 255 chars.",
    "409": "{\"detail\": \"Idempotency-Key already used with a different payload\"}: no link is created.",
    "422": "{\"detail\": [...pydantic errors]}: missing/invalid body or an invalid URL. Nothing is persisted.",
    "503": "{\"detail\": \"Could not allocate a unique short code, please retry\"} after all CODE_MAX_ATTEMPTS collided. Also {\"detail\": \"Service temporarily unavailable\"} on a DB error."
   },
