   "method": "GET",
   "path": "/{code}",
   "summary": "Redirect to the original URL and record a click event. (HEAD /{code} is also implemented with the same status and Location, without recording a click, and is hidden from the schema.)",
   "request": "Path code. Headers Referer and User-Agent are optional and recorded after truncation.",
   "responses": {
    "307": "Empty body. Location equals the stored URL exactly. Cache-Control: no-store. One click event is recorded (best-effort).",
    "404": "{\"detail\": \"Link not found\"}: no click is recorded",
    "410": "{\"detail\": \"Link has been deactivated\"}: no click is recorded"
