 "decisions": [
  {
   "id": "ADR-1",
   "title": "Strict layering with services owning transactions",
   "decision": "Routers in app/api depend only on services, schemas and core. Services accept a SQLAlchemy Session plus plain config values, use repositories, and alone call commit()/rollback(). Repositories only add/flush/query. Models import only sqlalchemy. Domain exceptions live in app/core/errors.py, which keeps services free of FastAPI imports.",
   "rationale": "Meets NFR-6, makes services unit-testable without HTTP, and puts the transaction boundaries needed for the retry/replay logic (NFR-5) in one place.",
   "alternatives": [
    "Fat routers that call the ORM directly",
    "Unit-of-work abstraction (unnecessary for this size)"
   ]
  },
  {
   "id": "ADR-2",
   "title": "Random base62 codes backed by a DB unique constraint and retry",
   "decision": "codes.generate_code(length) uses secrets.choice over [A-Za-z0-9]. The service inserts and flushes. On IntegrityError it rolls back and retries with a new code, up to CODE_MAX_ATTEMPTS (default 5). A reserved candidate (compared case-insensitively against RESERVED_CODES) uses up an attempt and is regenerated. When attempts run out the service raises a 503.",
   "rationale": "With 62^7 \u2248 3.5e12 codes collisions are rare. The DB constraint guarantees uniqueness across instances (NFR-5, NFR-9). Codes are unguessable (NFR-2, R-1).",
   "alternatives": [
    "Hash of the URL (deterministic, enables enumeration, conflicts with the no-dedup rule)",
    "Sequential ID encoded in base62 (guessable)",
    "Pre-check with SELECT before insert (racy without the constraint anyway)"
   ]
  },
  {
   "id": "ADR-3",
   "title": "Idempotency via a table with a unique key and request hash, written in the link's transaction",
   "decision": "If the key exists: a matching request_hash replays the stored link (201, Idempotent-Replayed: true), and a different hash returns 409. Otherwise the link is inserted and flushed, then the key row is inserted and flushed in the same transaction, then the transaction commits. An IntegrityError on the key flush (a concurrent winner) rolls back both rows, after which the service re-reads the key and replays or returns 409. Keys are global and never expire (Q-3). Replays are rebuilt from the stored link row.",
   "rationale": "The DB constraint guarantees at most one link per key even with concurrent requests or several instances (FR-4, R-7). It never returns 500.",
   "alternatives": [
    "Store the full response body JSON",
    "In-memory cache (violates NFR-9)",
    "Key expiry after 24h (deferred)"
   ]
  },
  {
   "id": "ADR-4",
   "title": "App factory with a per-app engine on app.state",
   "decision": "create_app(settings=None) builds Settings() when none are given, creates the engine and sessionmaker, and stores settings, engine and session_factory on app.state. get_db(request) and get_settings(request) read from app.state. Tables are created by Base.metadata.create_all(engine) in the lifespan startup, and the engine is disposed on shutdown.",
   "rationale": "Each test gets an isolated DB by passing Settings(database_url=tmp). There are no import-time side effects and no global mutable state (NFR-7, NFR-9).",
   "alternatives": [
    "Module-level global engine with dependency overrides",
    "lru_cache'd get_settings (stale across tests)",
    "Alembic migrations (out of scope)"
   ]
  },
  {
   "id": "ADR-5",
   "title": "Naive-UTC timestamps and Python-side day bucketing",
   "decision": "All DateTime columns are portable naive DateTime values holding UTC (models.base.utcnow() = datetime.now(timezone.utc).replace(tzinfo=None)). Response schemas convert to tz-aware UTC on output. clicks_per_day fetches only created_at for rows in the window and groups by .date() in Python. top_referrers uses SQL GROUP BY referrer, followed by a deterministic Python sort and a cut to 10.",
   "rationale": "Avoids database-specific date functions and NULL ordering differences (R-6, FR-12), and gives identical serialization for replays.",
   "alternatives": [
    "func.date() GROUP BY in SQL (return type differs per DB)",
    "timezone-aware columns (SQLite drops tzinfo anyway)"
   ]
  },
  {
   "id": "ADR-6",
   "title": "Raw 307 Response for redirects; ASCII-only target URLs",
   "decision": "The redirect handler returns Response(status_code=307, headers={'Location': url, 'Cache-Control': 'no-store'}) instead of starlette's RedirectResponse, which percent-quotes the URL. URL validation additionally rejects non-ASCII characters (clients must send punycode or percent-encoded URLs).",
   "rationale": "FR-5 requires Location to equal the stored URL exactly. Response headers are latin-1 encoded, so non-ASCII would otherwise cause 500s.",
   "alternatives": [
    "RedirectResponse (alters the URL)",
    "Normalize/IDNA-encode on input (violates the store-unchanged assumption)"
   ]
  },
  {
   "id": "ADR-7",
   "title": "Centralized JSON error handling with a middleware catch-all",
   "decision": "AppError subclasses carry status_code and detail: BadRequestError 400, NotFoundError 404, ConflictError 409, GoneError 410, ServiceUnavailableError 503. Handlers are registered for AppError, StarletteHTTPException (404/405, keeping headers such as Allow), RequestValidationError (422), SQLAlchemyError (503 'Service temporarily unavailable', logged), and Exception (500). RequestLoggingMiddleware also wraps call_next in try/except: an exception is logged with its traceback and answered with 500 {\"detail\": \"Internal Server Error\"}.",
   "rationale": "Meets FR-11 and NFR-3: error bodies never contain exception text, and DB outages become 503 rather than 500.",
   "alternatives": [
    "Per-route try/except",
    "Relying on FastAPI defaults (the 500 is plain text)"
   ]
  },
  {
   "id": "ADR-8",
   "title": "Synchronous, best-effort click recording",
   "decision": "After resolving an active link, the service inserts a ClickEvent and commits in its own small transaction. Any exception rolls back and is logged (logger.exception, without the IP), and the 307 is still returned. HEAD requests never record clicks.",
   "rationale": "Q-5 default: the redirect must not fail because of analytics (FR-8, R-4). HEAD is not a real visit.",
   "alternatives": [
    "Background tasks / async queue (out of scope)",
    "Failing the redirect when recording fails"
   ]
  },
  {
   "id": "ADR-9",
   "title": "No authentication in this iteration",
   "decision": "The /api/links router has no auth dependency, but is structured so that a future Depends(require_api_key) can be added at router level without changing the contract.",
   "rationale": "Q-1 default; tracked as a risk.",
   "alternatives": [
    "Static X-API-Key",
    "Per-user accounts"
   ]
  },
  {
   "id": "ADR-10",
   "title": "Readiness via the shared get_db dependency",
   "decision": "/readyz declares db: Session = Depends(get_db) and runs db.execute(text('SELECT 1')) inside try/except Exception, raising ServiceUnavailableError('Database is not ready') on failure. If an overridden get_db itself raises a SQLAlchemyError, the global SQLAlchemyError handler returns 503 too.",
   "rationale": "Tests can simulate a DB outage through app.dependency_overrides[get_db] (FR-10). No exception text is leaked.",
   "alternatives": [
    "Probe via app.state.engine directly (overrides would not apply)"
   ]
  }
 ],
 "risks": [
  {
   "id": "RK-1",
   "description": "Without authentication anyone who knows a code can deactivate a link or read its stats (Q-1).",
   "likelihood": "medium",
   "impact": "high",
   "mitigation": "Codes are high-entropy. The router is ready for an API-key dependency. Escalate before public launch."
  },
  {
   "id": "RK-2",
   "description": "The catch-all GET /{code} could shadow fixed routes, or test-added routes registered after it.",
   "likelihood": "medium",
   "impact": "medium",
   "mitigation": "Register the redirect router last in create_app. The reserved-word list is applied in code generation. Tests that add ad-hoc routes must use multi-segment paths such as /_test/boom, which /{code} cannot match."
  },
  {
   "id": "RK-3",
   "description": "SQLite 'database is locked' errors under concurrent writes.",
   "likelihood": "medium",
   "impact": "medium",
   "mitigation": "check_same_thread=False, short transactions, best-effort click recording, SQLAlchemyError mapped to 503. Recommend Postgres via DATABASE_URL for production."
  },
  {
   "id": "RK-4",
   "description": "uvicorn's access log prints client IPs, which would violate NFR-1.",
   "likelihood": "medium",
   "impact": "medium",
   "mitigation": "Run with `uvicorn app.main:app --no-access-log`. The app's own request log contains method, path (no query string), status and duration_ms only."
  },
  {
   "id": "RK-5",
   "description": "Python-side day bucketing loads every created_at in the window for very popular links.",
   "likelihood": "low",
   "impact": "medium",
   "mitigation": "Only one column is selected and the window is capped at 365 days. The (link_id, created_at) index serves the query. A future iteration can add pre-aggregated daily counters."
  },
  {
   "id": "RK-6",
   "description": "The idempotency race path is hard to exercise.",
   "likelihood": "low",
   "impact": "medium",
   "mitigation": "The service re-reads the key after an IntegrityError and returns 409 if it is still missing. Tests simulate the race by pre-inserting the key row after the first lookup (monkeypatch IdempotencyRepository.get_by_key to return None once)."
  },
  {
   "id": "RK-7",
   "description": "Datetime serialization differences between the first response and a replay would break FR-4's identical-body check.",
   "likelihood": "low",
   "impact": "medium",
   "mitigation": "Both responses are built from DB-loaded attributes (expire_on_commit=True reloads after commit). Schemas normalize datetimes to tz-aware UTC."
  }
 ],
 "work_packages": [
  {
   "id": "WP-1",
